#include "../plugins/autolevel/al_repo_compile.cpp"
#include <iostream>
using namespace al;
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
static Repo fixture(){Repo r;r.useFilling=false;BlockAsset a;a.uid="a";a.name="A";a.variants[0].sideIds[3]=1;a.actionsGroups={"Full Rotate On Z"};r.blocks={a};return r;}
int main(){try{
 auto r=fixture();auto rt=compileRepo(r);check(rt.states.size()==6,"four rotations and builtins");for(int l=0;l<int(rt.layerRange.size());l++){check(rt.builtin(l,0)>=0&&rt.builtin(l,1)>=0,"builtins each layer");int end=rt.layerRange[l].begin;for(auto range:rt.groupRange[l]){check(range.begin==end&&range.end>=range.begin,"nonoverlapping group ranges");end=range.end;}check(end==rt.layerRange[l].end,"partition complete");}
 r.blocks[0].variants[0].sideIds.v={1,0,1,1,0,1};rt=compileRepo(r);check(rt.states.size()==3&&!rt.warnings.empty(),"symmetric cross deduplicated");
 r=fixture();r.blocks[0].actionsGroups.clear();auto b=r.blocks[0];b.uid="b";b.name="B";b.variants[0].sideIds={};b.variants[0].sideIds[0]=1;r.blocks.push_back(b);r.bannedConnections={{{{"a",0},3},{{"b",0},0}}};rt=compileRepo(r);int ai=-1,bi=-1;for(size_t i=0;i<rt.states.size();i++){if(rt.states[i].blockUid=="a")ai=i;if(rt.states[i].blockUid=="b")bi=i;}check(!rt.compatible(ai,3,bi)&&!rt.compatible(bi,0,ai),"banned symmetric");r.bannedConnections.clear();r.exclusiveConnections={{{{"a",0},3},{{"b",0},0}}};rt=compileRepo(r);check(rt.conn[3][ai]==std::vector<int>{bi},"exclusive only partner");
 r=fixture();r.blocks[0].variants[0].sideIds={};r.blocks[0].actionsGroups.clear();BlockAsset up;up.uid="up";up.name="UP";up.variants[0].layerSettings.layer=1;r.blocks.push_back(up);rt=compileRepo(r);int ui=-1;ai=-1;for(size_t i=0;i<rt.states.size();i++){if(rt.states[i].blockUid=="up")ui=i;if(rt.states[i].blockUid=="a"&&!rt.states[i].isFiller)ai=i;}auto uppers=rt.upperOf(rt.builtin(0,0));check(std::find(uppers.begin(),uppers.end(),ui)!=uppers.end(),"no dependency only above Empty");check(!rt.upper[ai].empty()&&rt.states[rt.upper[ai][0]].isFiller,"filler for unlinked author");r.blocks.back().variants[0].layerSettings.layer=2;bool rejected=false;try{compileRepo(r);}catch(const std::exception& e){rejected=std::string(e.what()).find("layer number 1")!=std::string::npos;}check(rejected,"missing author layer diagnostic");
 Repo big;big.useFilling=false;BigBlockAsset bb;bb.uid="big";bb.name="2x2";bb.size={2,2,1};bb.actionsGroups={"Full Rotate On Z"};bb.data.resize(4);for(int c=0;c<4;c++){BlockAsset p;p.uid="p"+std::to_string(c);p.name=p.uid;p.variants[0].weight=4;p.variants[0].bigBlockUid=bb.uid;bb.data[c]={{p.uid,0}};big.blocks.push_back(p);}big.bigBlocks={bb};rt=compileRepo(big);check(rt.states.size()==18,"big block 16 part states");std::set<Id> internals;for(auto& s:rt.states)if(!s.bigBlockUid.empty()){check(s.weight==1,"part weight divided by volume");for(auto id:s.baseIds.v)if(id)internals.insert(id);}check(internals.size()==16,"fresh internal IDs per orientation");
 Repo expanded=fixture();BlockAsset other=expanded.blocks[0];other.uid="b";other.name="B";other.variants[0].sideIds={};other.variants[0].sideIds[0]=1;expanded.blocks.push_back(other);expanded.bannedConnections={{{{"a",0},3},{{"b",0},0}}};auto expandedRt=compileRepo(expanded);for(size_t i=0;i<expandedRt.states.size();i++)if(expandedRt.states[i].blockUid=="a")for(int d=0;d<6;d++)if(expandedRt.states[i].baseIds[d]==1)for(int neighbor:expandedRt.conn[d][i])check(expandedRt.states[neighbor].blockUid!="b","ban expands over every rotated action variant");
 Repo c=fixture();c.blocks[0].actionsGroups.clear();c.blocks[0].variants[0].sideIds={};b=c.blocks[0];b.uid="b";b.name="B";c.blocks.push_back(b);makeConnection(c,{{"a",0},3},{{"b",0},0});check(c.blocks[0].variants[0].sideIds[3]==1&&c.blocks[1].variants[0].sideIds[0]==1,"connect neither");c.blocks[0].variants[0].sideIds[2]=1;makeConnection(c,{{"a",0},2},{{"b",0},5});check(c.blocks[1].variants[0].sideIds[5]==1,"connect only src");c.blocks[0].variants[0].sideIds[0]=0;makeConnection(c,{{"a",0},0},{{"b",0},0});check(c.blocks[0].variants[0].sideIds[0]==1,"connect only dst");c.blocks[1].variants[0].sideIds[2]=c.blocks[1].variants[0].sideIds[3]=2;makeConnection(c,{{"a",0},3},{{"b",0},2});check(c.blocks[1].variants[0].sideIds[3]==1,"connect merges classes");IDGenerator ids(std::set<Id>{1,2,4});check(ids.next()==3&&ids.next()==5,"ID generator fills holes");

 r=fixture();BlockAsset top=r.blocks[0];top.uid="top";top.name="Top";top.variants[0].layerSettings.layer=1;top.variants[0].layerSettings.dependencies={{"a",0}};r.blocks.push_back(top);rt=compileRepo(r);int pairs=0;for(size_t a=0;a<rt.states.size();a++)if(rt.states[a].blockUid=="a"&&!rt.states[a].isFiller)for(int t:rt.upper[a])if(rt.states[t].blockUid=="top"){check(rt.states[a].actions==rt.states[t].actions,"Matching action sequence");pairs++;}check(pairs==4,"Matching pairs only");r.blocks[1].variants[0].layerSettings.resolve=Resolve::AllToAll;rt=compileRepo(r);pairs=0;for(size_t a=0;a<rt.states.size();a++)if(rt.states[a].blockUid=="a"&&!rt.states[a].isFiller)for(int t:rt.upper[a])if(rt.states[t].blockUid=="top")pairs++;check(pairs==16,"AllToAll expands all orientations");
 r.blocks[1].variants[0].layerSettings.layer=2;BlockAsset middle;middle.uid="middle";middle.name="middle";middle.variants[0].layerSettings.layer=1;r.blocks.push_back(middle);rt=compileRepo(r);bool traced=false;for(size_t a=0;a<rt.states.size();a++)if(rt.states[a].blockUid=="a"&&rt.states[a].isFiller&&rt.states[a].layer.layer==1)for(int t:rt.upper[a])traced|=rt.states[t].blockUid=="top";check(traced,"distant dependency traced through filler");
 std::cout<<"PASS repo: rotations/symmetry, group ranges, big part IDs/weights, banned/exclusive, layers/fillers, all connection cases\n";
 }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
